/** Roster-aware: pre-primary (âˆ’1 Nursery / 0 KG) use the roster label; 1..5 stay "à¦¶à§à¦°à§‡à¦£à¦¿ N" / "Class N". */
export const classLevelLabel = (level: number): string => {
  const roster = pick(ROSTER_CLASS_LABELS_BN, ROSTER_CLASS_LABELS_EN);
  if (level <= 0) return roster[level as RosterClassLevel] ?? (_lang === "en" ? `Class ${bnNum(level)}` : `à¦¶à§à¦°à§‡à¦£à¦¿ ${bnNum(level)}`);
  return _lang === "en" ? `Class ${bnNum(level)}` : `à¦¶à§à¦°à§‡à¦£à¦¿ ${bnNum(level)}`;
};

export const genderLabel = (v?: string | null): string => {
  const en = _lang === "en";
  return v === "male" ? (en ? "Male" : "à¦›à§‡à¦²à§‡")
    : v === "female" ? (en ? "Female" : "à¦®à§‡à¦¯à¦¼à§‡")
    : v === "other" ? (en ? "Other" : "à¦…à¦¨à§à¦¯à¦¾à¦¨à§à¦¯")
    : DASH;
};

/** Bilingual label for a message-template feature group (MT-3, D-#128). */
export const mtGroupLabel = (group: string): string => {
  switch (group) {
    case "classNote": return STR.mtGrpClassNote;
    case "homework": return STR.mtGrpHomework;
    case "review": return STR.mtGrpReview;
    case "cover": return STR.mtGrpCover;
    case "bell": return STR.mtGrpBell;
    case "attendance": return STR.mtGrpAttendance;
    case "library": return STR.mtGrpLibrary;
    case "assignment": return STR.mtGrpAssignment;
    case "credential": return STR.mtGrpCredential;
    case "tracker": return STR.mtGrpTracker;
    default: return group;
  }
};

